import { defineSchema } from "../../schemas/index.js";
export const getModelProviderSchema = defineSchema((v) => v.enum(["openai", "anthropic", "google", "local"]));
export const getAgentStatusSchema = defineSchema((v) => v.enum([
    "idle",
    "thinking",
    "tool_execution",
    "streaming",
    "completed",
    "error",
]));
export const getMemoryConfigSchema = defineSchema((v) => v.object({
    type: v.enum(["conversation", "buffer", "summary"]),
    maxTokens: v.number().int().positive().optional(),
    maxMessages: v.number().int().positive().optional(),
    // Persist history across calls on the agent instance. Defaults to true when
    // a memory config is provided; set false to keep every call isolated.
    enabled: v.boolean().optional(),
}));
export const getEdgeConfigSchema = defineSchema((v) => v.object({
    enabled: v.boolean(),
    maxSteps: v.number().int().positive().optional(),
    timeoutMs: v.number().int().positive().optional(),
    streaming: v.boolean().optional(),
}));
export const getToolCallPartWithArgsSchema = defineSchema((v) => v.object({
    type: v.string().regex(/^tool-.+$/),
    toolCallId: v.string(),
    toolName: v.string(),
    args: v.record(v.string(), v.unknown()),
    inputText: v.string().optional(),
    providerExecuted: v.boolean().optional(),
    supportsDeferredResults: v.boolean().optional(),
}));
export const getToolCallPartWithInputSchema = defineSchema((v) => v.object({
    type: v.string().regex(/^tool-.+$/),
    toolCallId: v.string(),
    toolName: v.string(),
    input: v.record(v.string(), v.unknown()),
    inputText: v.string().optional(),
    providerExecuted: v.boolean().optional(),
    supportsDeferredResults: v.boolean().optional(),
}));
export const getToolCallPartSchema = defineSchema((v) => v.union([
    getToolCallPartWithArgsSchema(),
    getToolCallPartWithInputSchema(),
]));
export const getToolResultPartSchema = defineSchema((v) => v.object({
    type: v.literal("tool-result"),
    toolCallId: v.string(),
    toolName: v.string(),
    result: v.unknown(),
    providerExecuted: v.boolean().optional(),
}));
/** Compatibility policy for the legacy inline tool-call message part. */
export const AGENT_SCHEMA_LEGACY_TOOL_CALL_PART_POLICY = {
    status: "compatibility-retained",
    legacyShape: '{ type: "tool-call", toolCallId, toolName, args }',
    canonicalShape: 'tool-prefixed message parts with "args" or "input"',
    removalGate: "Remove only in a planned breaking release after migration guidance and stored-message backfill coverage exist.",
};
// Helper for the inline tool-call alternative within MessagePartSchema.
// Keep this branch in sync with AGENT_SCHEMA_LEGACY_TOOL_CALL_PART_POLICY.
const inlineToolCallPartShape = (v) => v.object({
    type: v.literal("tool-call"),
    toolCallId: v.string(),
    toolName: v.string(),
    args: v.record(v.string(), v.unknown()),
});
const sourceUrlPartShape = (v) => v.object({
    type: v.literal("source-url"),
    sourceId: v.string(),
    url: v.string(),
    title: v.string().optional(),
});
const sourceDocumentPartShape = (v) => v.object({
    type: v.literal("source-document"),
    sourceId: v.string(),
    title: v.string(),
    mediaType: v.string().optional(),
    filename: v.string().optional(),
});
const attachmentMetadataFields = (v) => ({
    filename: v.string().optional(),
    uploadId: v.string().optional(),
    upload_id: v.string().optional(),
    uploadPath: v.string().optional(),
    upload_path: v.string().optional(),
});
export const getMessagePartSchema = defineSchema((v) => v.union([
    v.object({
        type: v.literal("text"),
        text: v.string(),
    }),
    v.object({
        type: v.literal("reasoning"),
        text: v.string().optional(),
        signature: v.string().optional(),
        redactedData: v.string().optional(),
    }),
    getToolCallPartSchema(),
    inlineToolCallPartShape(v),
    getToolResultPartSchema(),
    sourceUrlPartShape(v),
    sourceDocumentPartShape(v),
    v.object({
        type: v.literal("image"),
        url: v.string(),
        mediaType: v.string(),
        ...attachmentMetadataFields(v),
    }),
    v.object({
        type: v.literal("file"),
        url: v.string(),
        mediaType: v.string(),
        ...attachmentMetadataFields(v),
    }),
]));
export const getMessageSchema = defineSchema((v) => v.object({
    id: v.string(),
    role: v.enum(["user", "assistant", "system", "tool"]),
    parts: v.array(getMessagePartSchema()),
    timestamp: v.number().int().nonnegative().optional(),
    metadata: v.record(v.string(), v.unknown()).optional(),
}));
export const getStreamToolCallSchema = defineSchema((v) => v.object({
    id: v.string(),
    name: v.string(),
    arguments: v.record(v.string(), v.unknown()),
}));
export const getToolCallSchema = defineSchema((v) => v.object({
    id: v.string(),
    name: v.string(),
    args: v.record(v.string(), v.unknown()),
    inputText: v.string().optional(),
    status: v.enum(["pending", "executing", "completed", "error"]),
    result: v.unknown().optional(),
    error: v.string().optional(),
    executionTime: v.number().nonnegative().optional(),
}));
export const getAgentResponseSchema = defineSchema((v) => v.object({
    text: v.string(),
    messages: v.array(getMessageSchema()),
    toolCalls: v.array(getToolCallSchema()),
    status: getAgentStatusSchema(),
    thinking: v.string().optional(),
    // Parsed `outputSchema` value. Typed precisely by `AgentResponse<TOutput>`;
    // the runtime schema only has to accept it.
    data: v.unknown().optional(),
    object: v.unknown().optional(),
    usage: v
        .object({
        promptTokens: v.number().int().nonnegative(),
        completionTokens: v.number().int().nonnegative(),
        totalTokens: v.number().int().nonnegative(),
        cachedInputTokens: v.number().int().nonnegative().optional(),
        cacheCreationInputTokens: v.number().int().nonnegative().optional(),
        cacheCreation1hInputTokens: v.number().int().nonnegative().optional(),
        cacheReadInputTokens: v.number().int().nonnegative().optional(),
        reasoningTokens: v.number().int().nonnegative().optional(),
        billableInputTokens: v.number().int().nonnegative().optional(),
        billableOutputTokens: v.number().int().nonnegative().optional(),
        costUsd: v.number().nonnegative().optional(),
        providerInputCostUsd: v.number().nonnegative().optional(),
        providerOutputCostUsd: v.number().nonnegative().optional(),
        providerCostUsd: v.number().nonnegative().optional(),
        veryfrontInputChargeUsd: v.number().nonnegative().optional(),
        veryfrontOutputChargeUsd: v.number().nonnegative().optional(),
        veryfrontChargeUsd: v.number().nonnegative().optional(),
        veryfrontBilledUsd: v.number().nonnegative().optional(),
        costCredits: v.number().nonnegative().optional(),
        costSource: v.enum(["gateway", "missing", "partial"]).optional(),
        billingMode: v.enum(["direct", "deferred"]).optional(),
        usageCaptureStatus: v.enum(["complete", "partial", "missing"]).optional(),
    })
        .optional(),
    metadata: v.record(v.string(), v.unknown()).optional(),
}));
export const getAgentContextSchema = defineSchema((v) => v.object({
    agentId: v.string(),
    model: v.string().optional(),
    input: v.union([v.string(), v.array(getMessageSchema())]),
    data: v.record(v.string(), v.unknown()).optional(),
    platform: v.any(), // Platform type is complex
    metadata: v.record(v.string(), v.unknown()).optional(),
}));
